//! Property tests for `sync::mirror` (ADR-0026, `sync.md` 2 and 10): devices that sync through one remote
//! converge, whatever the order of writes and syncs and however flaky the remote is.
//!
//! The model is several devices, each with its own local folder, and one remote. A device writes the way the
//! real ones do: op files and snapshots named by their owner, and `vault.json` revisions that also rewrite the
//! device's record. Everything is generated bytes; nothing here is a real secret.

use std::collections::{BTreeMap, BTreeSet};
use std::sync::atomic::{AtomicUsize, Ordering};

use figlock_session::sync::{Opts, Report, SyncError, Warning, mirror};
use figlock_store::{BlobStore, Entry, LocalFolder, StoreError};
use proptest::prelude::*;
use sha2::{Digest, Sha256};
use tempfile::TempDir;

const VAULT: &str = "vault-1";
const IDS: [&str; 4] = ["aa", "bb", "cc", "dd"];

type Files = BTreeMap<String, Vec<u8>>;

/// Everything in a store, the way the vault would read it.
fn files(s: &dyn BlobStore) -> Files {
    let mut out = Files::new();
    for e in s.list("").unwrap() {
        out.insert(e.path.clone(), s.get(&e.path).unwrap());
    }
    out
}

/// `nonce` stands in for the fresh nonce and signature that make two real writes differ byte for byte.
fn vault_json(revision: u64, nonce: u32) -> Vec<u8> {
    serde_json::json!({ "vault_id": VAULT, "revision": revision, "nonce": nonce })
        .to_string()
        .into_bytes()
}

fn revision(s: &dyn BlobStore) -> Option<u64> {
    let v: serde_json::Value = serde_json::from_slice(&s.get("vault.json").ok()?).ok()?;
    v["revision"].as_u64()
}

/// A remote that works for `budget` calls and then fails, like a connection dropping part way through a sync.
struct Faulty<'a> {
    inner: &'a LocalFolder,
    budget: AtomicUsize,
    error: StoreError,
}

impl Faulty<'_> {
    fn spend(&self) -> Result<(), StoreError> {
        self.budget
            .try_update(Ordering::SeqCst, Ordering::SeqCst, |n| n.checked_sub(1))
            .map(|_| ())
            .map_err(|_| self.error)
    }
}

impl BlobStore for Faulty<'_> {
    fn get(&self, p: &str) -> Result<Vec<u8>, StoreError> {
        self.spend()?;
        self.inner.get(p)
    }
    fn put_new(&self, p: &str, b: &[u8]) -> Result<(), StoreError> {
        self.spend()?;
        self.inner.put_new(p, b)
    }
    fn put_replace(&self, p: &str, b: &[u8]) -> Result<(), StoreError> {
        self.spend()?;
        self.inner.put_replace(p, b)
    }
    fn list(&self, p: &str) -> Result<Vec<Entry>, StoreError> {
        self.spend()?;
        self.inner.list(p)
    }
    fn delete(&self, p: &str) -> Result<(), StoreError> {
        self.spend()?;
        self.inner.delete(p)
    }
}

struct Device {
    id: &'static str,
    local: LocalFolder,
    _dir: TempDir,
    /// A sync has finished here, so an empty remote means "lost" and only own files are pushed.
    synced: bool,
    ops: u32,
    snaps: u32,
}

struct World {
    devices: Vec<Device>,
    remote: LocalFolder,
    _dir: TempDir,
    /// Files a device compacted away: deleted from the remote and from the compactor, but other devices
    /// may still hold a stale copy.
    compacted: BTreeSet<String>,
    unique: u32,
}

fn folder() -> (TempDir, LocalFolder) {
    let d = tempfile::tempdir().unwrap();
    let s = LocalFolder::open(d.path()).unwrap();
    (d, s)
}

impl World {
    /// `n` devices. The first created the vault (revision 1, its record) and has uploaded it; the others are
    /// empty and join by syncing.
    fn new(n: usize) -> World {
        let (dir, remote) = folder();
        let devices = IDS[..n]
            .iter()
            .map(|id| {
                let (_dir, local) = folder();
                Device {
                    id,
                    local,
                    _dir,
                    synced: false,
                    ops: 0,
                    snaps: 0,
                }
            })
            .collect();
        let mut w = World {
            devices,
            remote,
            _dir: dir,
            compacted: BTreeSet::new(),
            unique: 0,
        };
        let first = &w.devices[0];
        first
            .local
            .put_replace("vault.json", &vault_json(1, 0))
            .unwrap();
        first
            .local
            .put_replace(&format!("devices/{}.json", first.id), b"rec-aa-0")
            .unwrap();
        w.sync(0, None).expect("the first upload works");
        w
    }

    fn unique(&mut self) -> u32 {
        self.unique += 1;
        self.unique
    }

    fn sync(&mut self, d: usize, fault: Option<Fault>) -> Result<Report, SyncError> {
        let dev = &mut self.devices[d];
        let opts = Opts {
            own_device: Some(dev.id),
            // As `sync::run`: everything goes up until a sync has finished once.
            push_all: !dev.synced,
        };
        let r = match fault {
            None => mirror(&dev.local, &self.remote, &opts),
            Some(f) => mirror(
                &dev.local,
                &Faulty {
                    inner: &self.remote,
                    budget: AtomicUsize::new(f.budget),
                    error: f.error,
                },
                &opts,
            ),
        };
        if r.is_ok() {
            dev.synced = true;
        }
        r
    }

    fn apply(&mut self, a: &Action) {
        let n = self.devices.len();
        let u = self.unique();
        match *a {
            Action::Op(d) => {
                let dev = &mut self.devices[d % n];
                dev.ops += 1;
                let path = format!("log/{}/{:08}.op", dev.id, dev.ops);
                dev.local
                    .put_new(&path, format!("op-{u}").as_bytes())
                    .unwrap();
            }
            Action::Snap(d) => {
                let dev = &mut self.devices[d % n];
                dev.snaps += 1;
                let path = format!("snap/{}-{:08}.snap", dev.id, dev.snaps);
                dev.local
                    .put_new(&path, format!("snap-{u}").as_bytes())
                    .unwrap();
            }
            Action::Record(d) => {
                let dev = &self.devices[d % n];
                let path = format!("devices/{}-{u}.json", dev.id);
                dev.local.put_replace(&path, b"rec").unwrap();
            }
            // A new `vault.json` revision rewrites the writer's own record along with it (a rotation).
            Action::Bump(d) => {
                let dev = &self.devices[d % n];
                if let Some(rev) = revision(&dev.local) {
                    dev.local
                        .put_replace("vault.json", &vault_json(rev + 1, u))
                        .unwrap();
                    let rec = format!("devices/{}.json", dev.id);
                    dev.local
                        .put_replace(&rec, format!("rec-{u}").as_bytes())
                        .unwrap();
                }
            }
            Action::Compact(d, k) => {
                let dev = &self.devices[d % n];
                let own = format!("log/{}/", dev.id);
                let mine: Vec<String> = dev
                    .local
                    .list(&own)
                    .unwrap()
                    .into_iter()
                    .map(|e| e.path)
                    .collect();
                if !mine.is_empty() {
                    let path = &mine[k % mine.len()];
                    let _ = dev.local.delete(path);
                    let _ = self.remote.delete(path);
                    self.compacted.insert(path.clone());
                }
            }
            Action::Sync(d, fault) => {
                let before = files(&self.devices[d % n].local);
                let had_synced = self.devices[d % n].synced;
                let r = self.sync(d % n, fault);
                self.check_sync(d % n, &before, had_synced, fault, &r);
            }
        }
    }

    /// What must hold after every sync, healthy or not.
    fn check_sync(
        &self,
        d: usize,
        before: &Files,
        had_synced: bool,
        fault: Option<Fault>,
        r: &Result<Report, SyncError>,
    ) {
        let (local, remote) = (files(&self.devices[d].local), files(&self.remote));
        match (fault, r) {
            (None, r) => {
                r.as_ref().expect("a healthy remote syncs");
            }
            (Some(f), Err(e)) => assert_eq!(
                *e,
                match f.error {
                    StoreError::Unauthorized => SyncError::SignIn,
                    _ => SyncError::Offline,
                },
                "a failing remote is reported as the failure it is"
            ),
            (Some(_), Ok(_)) => {}
        }
        // A failing remote only ever adds what the remote holds; it never loses or rewrites a local file.
        // `vault.json` and `devices/` may legitimately follow a newer remote revision, so they are exempt.
        for (path, bytes) in before {
            if path == "vault.json" || path.starts_with("devices/") {
                continue;
            }
            assert_eq!(local.get(path), Some(bytes), "local lost or changed {path}");
        }
        for (path, bytes) in &local {
            if !before.contains_key(path) {
                let came_from = remote.get(path).or_else(|| before.get(path));
                assert!(
                    came_from == Some(bytes) || self.compacted.contains(path),
                    "local gained {path} from nowhere"
                );
            }
        }
        // Own-files-only push: after a device has synced once, a file compacted away is never put back.
        if had_synced {
            for path in &self.compacted {
                assert!(!remote.contains_key(path), "compacted {path} came back");
            }
        }
    }

    /// Every device syncs against a healthy remote until a full round changes nothing.
    fn settle(&mut self) {
        for round in 0..6 {
            let mut changed = false;
            for d in 0..self.devices.len() {
                let r = self.sync(d, None).expect("a healthy remote syncs");
                changed |= r.pulled + r.pushed > 0;
            }
            if !changed {
                return;
            }
            assert!(
                round < 5,
                "six rounds against a healthy remote did not settle"
            );
        }
    }

    /// Every side holds the same files, except stale copies of files that were compacted away.
    fn assert_converged(&self) {
        let strip = |mut f: Files| {
            f.retain(|p, _| !self.compacted.contains(p));
            f
        };
        let remote = strip(files(&self.remote));
        for dev in &self.devices {
            assert_eq!(
                strip(files(&dev.local)),
                remote,
                "device {} differs from the remote",
                dev.id
            );
        }
        for path in &self.compacted {
            assert!(
                !files(&self.remote).contains_key(path),
                "compacted {path} on the remote"
            );
        }
    }
}

#[derive(Clone, Copy, Debug)]
struct Fault {
    /// Calls the remote answers before it fails.
    budget: usize,
    error: StoreError,
}

#[derive(Clone, Debug)]
enum Action {
    Op(usize),
    Snap(usize),
    Record(usize),
    Bump(usize),
    Compact(usize, usize),
    Sync(usize, Option<Fault>),
}

fn fault() -> impl Strategy<Value = Fault> {
    (
        0usize..40,
        prop_oneof![
            Just(StoreError::Unavailable),
            Just(StoreError::Unauthorized)
        ],
    )
        .prop_map(|(budget, error)| Fault { budget, error })
}

fn action(flaky: bool) -> impl Strategy<Value = Action> {
    let sync = if flaky {
        proptest::option::weighted(0.5, fault()).boxed()
    } else {
        Just(None).boxed()
    };
    prop_oneof![
        3 => (0..4usize).prop_map(Action::Op),
        1 => (0..4usize).prop_map(Action::Snap),
        1 => (0..4usize).prop_map(Action::Record),
        2 => (0..4usize).prop_map(Action::Bump),
        1 => (0..4usize, 0..8usize).prop_map(|(d, k)| Action::Compact(d, k)),
        6 => (0..4usize, sync).prop_map(|(d, f)| Action::Sync(d, f)),
    ]
}

fn config() -> ProptestConfig {
    ProptestConfig {
        cases: 32,
        ..ProptestConfig::default()
    }
}

proptest! {
    #![proptest_config(config())]

    /// Random writes and sync orders across 2 to 4 devices end in the same files everywhere.
    #[test]
    fn devices_converge_through_the_remote(
        n in 2..=4usize,
        actions in proptest::collection::vec(action(false), 1..40),
    ) {
        let mut w = World::new(n);
        for a in &actions {
            w.apply(a);
        }
        w.settle();
        w.assert_converged();
    }

    /// The same, with a remote that fails at random points: a later healthy sync still converges and a failure
    /// never costs a local file.
    #[test]
    fn a_flaky_remote_only_delays_convergence(
        n in 2..=4usize,
        actions in proptest::collection::vec(action(true), 1..40),
    ) {
        let mut w = World::new(n);
        for a in &actions {
            w.apply(a);
        }
        w.settle();
        w.assert_converged();
    }

    /// Devices that each wrote the next `vault.json` revision differently all end on the lowest hash.
    #[test]
    fn a_vault_json_fork_has_one_winner_everywhere(
        n in 2..=4usize,
        order in proptest::collection::vec(0..4usize, 0..12),
    ) {
        let mut w = World::new(n);
        w.settle();
        let mut candidates = Vec::new();
        for d in 0..n {
            w.apply(&Action::Bump(d));
            let rev = revision(&w.devices[d].local).unwrap();
            candidates.push(w.devices[d].local.get("vault.json").unwrap());
            assert_eq!(rev, 2);
        }
        for d in order {
            w.apply(&Action::Sync(d, None));
        }
        w.settle();
        w.assert_converged();
        let lowest = candidates.iter().min_by_key(|c| Sha256::digest(c)).unwrap();
        prop_assert_eq!(&w.remote.get("vault.json").unwrap(), lowest);
    }

    /// A revocation at the highest revision is never undone by a stale device, whatever syncs before it lands.
    #[test]
    fn a_revocation_is_never_lost(
        n in 2..=4usize,
        before in proptest::collection::vec(action(false), 0..20),
        after in proptest::collection::vec(action(true), 0..20),
    ) {
        let mut w = World::new(n);
        w.devices[0].local.put_replace("devices/zz.json", b"rec-zz").unwrap();
        w.settle();
        for a in &before {
            // Stale devices keep writing; only the revoker bumps from here.
            if !matches!(a, Action::Bump(_)) {
                w.apply(a);
            }
        }
        w.settle();
        // The revoker holds the highest revision anywhere and drops zz's record.
        let top = w
            .devices
            .iter()
            .filter_map(|d| revision(&d.local))
            .chain(revision(&w.remote))
            .max()
            .unwrap();
        w.devices[0].local.put_replace("vault.json", &vault_json(top + 1, u32::MAX)).unwrap();
        w.devices[0].local.delete("devices/zz.json").unwrap();
        w.apply(&Action::Sync(0, None));
        for a in &after {
            if !matches!(a, Action::Bump(_) | Action::Record(_)) {
                w.apply(a);
            }
        }
        w.settle();
        w.assert_converged();
        prop_assert!(!files(&w.remote).contains_key("devices/zz.json"));
        for dev in &w.devices {
            prop_assert!(!files(&dev.local).contains_key("devices/zz.json"));
        }
    }

    /// A vault whose remote is empty after a sync is "lost": nothing goes up without confirmation, and a
    /// confirmed re-upload (and a first sync) pushes every local file, other devices' included.
    #[test]
    fn a_lost_remote_is_refilled_only_on_confirmation(
        actions in proptest::collection::vec(action(false), 0..20),
    ) {
        let mut w = World::new(2);
        for a in &actions {
            w.apply(a);
        }
        w.settle();
        for e in w.remote.list("").unwrap() {
            w.remote.delete(&e.path).unwrap();
        }
        let local = files(&w.devices[0].local);
        let r = w.sync(0, None);
        prop_assert_eq!(r, Err(SyncError::RemoteLost));
        prop_assert!(files(&w.remote).is_empty());
        prop_assert_eq!(files(&w.devices[0].local), local.clone());

        // The person confirms. Everything local goes up, stale copies of compacted files included: that is
        // what a re-upload means, so those are no longer "compacted away".
        w.devices[0].synced = false;
        w.compacted.retain(|p| !local.contains_key(p));
        w.sync(0, None).unwrap();
        prop_assert_eq!(files(&w.remote), local);
        w.settle();
        w.assert_converged();
    }

    /// Another vault is never merged, from either side, however much each holds.
    #[test]
    fn a_foreign_vault_is_never_merged(
        local in proptest::collection::vec(action(false), 0..10),
        theirs in 0..4u32,
    ) {
        let mut w = World::new(2);
        for a in &local {
            w.apply(a);
        }
        w.settle();
        let (remote_before, local_before) = (files(&w.remote), files(&w.devices[1].local));
        let foreign = serde_json::json!({ "vault_id": "other", "revision": 99 }).to_string();
        w.remote.put_replace("vault.json", foreign.as_bytes()).unwrap();
        for i in 0..theirs {
            w.remote.put_new(&format!("log/zz/{i:08}.op"), b"theirs").unwrap();
        }
        let remote_foreign = files(&w.remote);
        for d in 0..2 {
            prop_assert_eq!(w.sync(d, None), Err(SyncError::ForeignVault));
        }
        prop_assert_eq!(files(&w.remote), remote_foreign);
        prop_assert_eq!(files(&w.devices[1].local), local_before);
        prop_assert!(remote_before.len() <= files(&w.remote).len());
    }
}

/// The warning is what the person is told when their change lost a fork.
#[test]
fn a_fork_is_reported_to_the_device_that_meets_it() {
    let mut w = World::new(2);
    w.settle();
    w.apply(&Action::Bump(0));
    w.apply(&Action::Bump(1));
    w.sync(0, None).unwrap();
    let r = w.sync(1, None).unwrap();
    assert_eq!(r.warnings, vec![Warning::VaultJsonFork]);
}

/// A stale copy of a compacted file on a device that never pushes it is not a divergence, and a confirmed
/// re-upload from another device leaves it alone.
#[test]
fn a_stale_copy_survives_a_confirmed_reupload_without_resurrecting() {
    let mut w = World::new(3);
    w.apply(&Action::Op(0));
    w.apply(&Action::Sync(2, None));
    w.apply(&Action::Sync(1, None));
    w.apply(&Action::Compact(0, 0));
    for e in w.remote.list("").unwrap() {
        w.remote.delete(&e.path).unwrap();
    }
    w.devices[0].synced = false;
    w.sync(0, None).unwrap();
    w.settle();
    w.assert_converged();
}
